query:
alter table public.shops alter column owner_id drop not null;
insert into public.product_categories (name, slug, is_visible, sort_order) values ('น้ำผึ้งและผลิตภัณฑ์จากผึ้ง', 'honey-and-bee-products', true, 1), ('อาหารและเครื่องดื่ม', 'food-and-beverages', true, 2) on conflict (slug) do update set name = excluded.name, is_visible = excluded.is_visible, sort_order = excluded.sort_order;
insert into public.shops (name, slug, description, status) values ('HOBEE Official Store', 'hobee-official-store', 'สินค้า HOBEE จากเครือข่ายผู้ผลิตชุมชน', 'active'), ('ของดีชุมชนยะลา', 'yala-community-goods', 'สินค้าคัดสรรจากผู้ผลิตท้องถิ่น', 'active'), ('เครือข่ายชุมชน HOBEE', 'hobee-community-network', 'ของดีจากผู้ผลิตในเครือข่าย HOBEE', 'active') on conflict (slug) do update set name = excluded.name, description = excluded.description, status = excluded.status;
insert into public.products (shop_id, category_id, name, slug, description, price, compare_at_price, stock_quantity, status, origin, rating, review_count) values ((select id from public.shops where slug = 'hobee-official-store'), (select id from public.product_categories where slug = 'honey-and-bee-products'), 'HOBEE น้ำผึ้งชันโรงแท้ 100% สายพันธุ์อิตาม่า 700 กรัม', 'hobee-itama-stingless-bee-honey-700g', 'น้ำผึ้งชันโรงแท้ 100% สายพันธุ์อิตาม่า จากฟาร์มผึ้งชันโรง HOBEE นราธิวาส บรรจุขนาดสุทธิ 700 กรัม', 1290.00, 1590.00, 50, 'published', 'ฟาร์มผึ้งชันโรง HOBEE นราธิวาส', 5.0, 128), ((select id from public.shops where slug = 'yala-community-goods'), (select id from public.product_categories where slug = 'food-and-beverages'), 'น้ำผึ้งป่า ดอยสุเทพ 100%', 'wild-honey-doi-suthep', 'น้ำผึ้งป่าแท้ 100% จากกลุ่มอนุรักษ์ชันโรงและน้ำผึ้งป่า', 350.00, 390.00, 35, 'published', 'กลุ่มอนุรักษ์ชันโรงและน้ำผึ้งป่า', 4.8, 35), ((select id from public.shops where slug = 'yala-community-goods'), (select id from public.product_categories where slug = 'food-and-beverages'), 'กาแฟคั่วเข้ม อาราบิก้า 100%', 'dark-roast-arabica-coffee-250g', 'กาแฟอาราบิก้าคั่วเข้มแท้ 100% จากเกษตรกรในพื้นที่จังหวัดยะลา', 250.00, 290.00, 50, 'published', 'วิสาหกิจชุมชนกาแฟยะลา', 4.9, 48), ((select id from public.shops where slug = 'hobee-community-network'), (select id from public.product_categories where slug = 'food-and-beverages'), 'ข้าวหอมมะลิ เชียงใหม่ 1 กก.', 'chiang-mai-jasmine-rice-1kg', 'ข้าวหอมมะลิคุณภาพจากชุมชนเกษตรกร', 120.00, null, 40, 'published', 'ชุมชนเกษตรกรเชียงใหม่', 4.7, 22) on conflict (slug) do update set name = excluded.name, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, stock_quantity = excluded.stock_quantity, status = excluded.status, origin = excluded.origin, rating = excluded.rating, review_count = excluded.review_count, updated_at = timezone('utc', now());
